(function(api){
var mists=[], spr=null;
function mkSpr(){
  var s=api.canvas.ownerDocument.createElement('canvas');
  s.width=200; s.height=200;
  var c=s.getContext('2d');
  var g=c.createRadialGradient(100,100,10,100,100,100);
  g.addColorStop(0,'rgba(235,235,240,0.5)');
  g.addColorStop(0.6,'rgba(235,235,240,0.18)');
  g.addColorStop(1,'rgba(235,235,240,0)');
  c.fillStyle=g; c.fillRect(0,0,200,200);
  return s;
}
function num(k,d){ var p=api.params||{}; return p[k]!=null?+p[k]:d; }
function frame(dt){
  var W=api.width,H=api.height; if(!W||!H) return;
  var f=dt/16.6;
  if(!spr) spr=mkSpr();
  var n=Math.max(0,num('density',4)), spd=Math.max(0.2,num('speed',3))*0.06, wh=num('whiteness',4);
  var ctx=api.ctx;
  ctx.clearRect(0,0,W,H);
  while(mists.length<n*2){
    mists.push({x:api.rand(-200,W), y:api.rand(-60,H*0.8), r:api.rand(180,420), a:api.rand(0.2,0.45), v:api.rand(0.4,1.2)});
  }
  if(mists.length>n*2) mists.length=n*2;
  for(var i=0;i<mists.length;i++){
    var m=mists[i];
    m.x+=m.v*spd*f;
    if(m.x-m.r>W+200){ m.x=-m.r-50; m.y=api.rand(-60,H*0.8); }
    ctx.globalAlpha=m.a;
    var d2=m.r*2;
    ctx.drawImage(spr,m.x-m.r,m.y-m.r*0.4,d2,d2*0.4);
  }
  ctx.globalAlpha=1;
  if(wh>0){ ctx.fillStyle='rgba(235,235,240,'+(0.02*wh)+')'; ctx.fillRect(0,0,W,H); }
}
function clear(){ try{ api.ctx.clearRect(0,0,api.width,api.height); }catch(e){} mists=[]; }
return { frame:frame, clear:clear, resize:clear };
})
